class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;
  int _refreshCounter = 0;

  void _onRefreshAllPressed() async {
    final BuildContext context = this.context;
    setState(() {
      _refreshCounter++;
    });
    // ignore: unawaited_futures
    context.read<CurrencyRepository>().fetchRates(const CurrencyPageRequest(base: 'USD'));
    // ignore: unawaited_futures
    context.read<NewsRepository>().loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
  }

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = IndexedStack(
      index: _selectedIndex,
      children: <Widget>[
        CurrencyListPage(key: ValueKey(_refreshCounter)),
        NewsListPage(key: ValueKey(_refreshCounter)),
        const ProfilePage(),
      ],
    );
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(
        title: Text(loc.currencyRate),
        actions: <Widget>[
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: loc.refreshAll,
            onPressed: _onRefreshAllPressed,
          ),
        ],
      ),
      body: currentPage,
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _onRefreshAllPressed,
        label: Text(loc.refreshAll),
        icon: const Icon(Icons.sync),
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: [
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            BottomNavigationBarItem(
              icon: Icon(Icons.person),
              label: loc.profile,
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
